begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.pi(t text) returns uuid language sql immutable as $$select md5('publishing-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.pi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.pi(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-publisher@example.invalid',now(),now(),now() from unnest(array['owner','local','reader'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.pi('org'),'Publicação fictícia','publishing-test','active'),(pg_temp.pi('other'),'Outra organização fictícia','publishing-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.pi('a'),pg_temp.pi('org'),'Igreja fictícia A','a','headquarters'),(pg_temp.pi('b'),pg_temp.pi('org'),'Igreja fictícia B','b','campus'),(pg_temp.pi('c'),pg_temp.pi('org'),'Igreja fictícia C','c','campus'),(pg_temp.pi('outside'),pg_temp.pi('other'),'Outra igreja fictícia','outside','headquarters');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.pi(t||'-m'),pg_temp.pi('org'),pg_temp.pi(t),pg_temp.pi('a'),case t when 'owner' then 'owner'::public.membership_role when 'local' then 'secretary'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','local','reader'])t;
insert into public.membership_unit_access(organization_id,membership_id,unit_id,access_level,include_children) values(pg_temp.pi('org'),pg_temp.pi('local-m'),pg_temp.pi('a'),'manage',false);
create function pg_temp.pub(a text,i text default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.publishing_admin(pg_temp.pi('org'),pg_temp.pi('a'),a,case when i is null then null else pg_temp.pi(i) end,v,d)$$;
create function pg_temp.fields(k text default 'notice',s text default 'selected') returns jsonb language sql as $$select jsonb_build_object('kind',k,'title','Publicação fictícia '||k,'body','Conteúdo público fictício','source',case when k='channel' then 'https://www.youtube.com/channel/UCaaaaaaaaaaaaaaaaaaaaaa' when k in('video','live') then 'https://www.youtube.com/watch?v=aaaaaaaaaaa' else '' end,'poster','','category','','channel','','scope',s,'targets',jsonb_build_array(pg_temp.pi('a'),pg_temp.pi('b')),'group','','groupVersion',0,'provider',case when k='channel' then 'youtube' else '' end,'starts',case when k='live' then (now()+interval '1 hour')::text else '' end,'ends',case when k='live' then (now()+interval '2 hours')::text else '' end,'download',false,'share',true)$$;
select pg_temp.actor('reader');set local role authenticated;
select throws_ok($$select pg_temp.pub('list')$$,'42501','publishing_denied','membro não gerencia publicações');reset role;
select pg_temp.actor('owner');set local role authenticated;
select lives_ok($$select pg_temp.pub('group','group',0,jsonb_build_object('title','Grupo fictício','targets',jsonb_build_array(pg_temp.pi('a'),pg_temp.pi('b')),'active',true))$$,'grupo de igrejas criado');
select lives_ok($$select pg_temp.pub('save','notice',0,pg_temp.fields()||jsonb_build_object('scope','group','group',pg_temp.pi('group'),'groupVersion',1))$$,'rascunho por grupo');
select is(jsonb_array_length(public.member_public_feed(pg_temp.pi('org'),pg_temp.pi('a'))->'items'),0,'rascunho não aparece no portal');
select lives_ok($$select pg_temp.pub('publish','notice',1)$$,'publica em duas igrejas');
select is(jsonb_array_length(public.member_public_feed(pg_temp.pi('org'),pg_temp.pi('a'))->'items'),1,'igreja A recebe');
select is(jsonb_array_length(public.member_public_feed(pg_temp.pi('org'),pg_temp.pi('b'))->'items'),1,'igreja B recebe');
select is(jsonb_array_length(public.member_public_feed(pg_temp.pi('org'),pg_temp.pi('c'))->'items'),0,'igreja fora do grupo não recebe');
select throws_ok($$select public.member_church_admin(pg_temp.pi('org'),'unpublish',(public.member_public_feed(pg_temp.pi('org'),pg_temp.pi('a'))->'items'->0->>'id')::uuid)$$,'42501','publishing_managed_projection','cliente anterior não retira cópia de publicação compartilhada');
reset role;select pg_temp.actor('local');set local role authenticated;
select is(pg_temp.pub('list')->'items'->0->>'can_manage','false','gestor local consulta compartilhamento sem editar alcance');
select is(jsonb_array_length(pg_temp.pub('list')->'items'->0->'targets'),1,'não expõe destinos fora do alcance local');
select throws_ok($$select pg_temp.pub('archive','notice',2)$$,'42501','publishing_denied','gestor local não arquiva publicação de outras igrejas');
select throws_ok($$select pg_temp.pub('save','forged',0,pg_temp.fields())$$,'42501','publishing_denied','destino externo ao alcance é recusado');
select lives_ok($$select pg_temp.pub('save','local',0,pg_temp.fields('notice','all'))$$,'todas no alcance local cria apenas uma igreja');
select is(jsonb_array_length((select x->'targets' from jsonb_array_elements(pg_temp.pub('list')->'items')x where x->>'id'=pg_temp.pi('local')::text)),1,'todos nunca significa todo o ministério para gestor local');
reset role;select pg_temp.actor('owner');set local role authenticated;
select lives_ok($$select pg_temp.pub('save','channel',0,pg_temp.fields('channel'))$$,'canal YouTube cadastrado');
select lives_ok($$select pg_temp.pub('publish','channel',1)$$,'canal publicado');
select is(jsonb_array_length(public.member_publishing_catalog(pg_temp.pi('org'),pg_temp.pi('b'),'channel')->'items'),1,'canal chega ao público da igreja B');
select lives_ok($$select pg_temp.pub('save','category',0,pg_temp.fields('category'))$$,'categoria cadastrada');
select lives_ok($$select pg_temp.pub('publish','category',1)$$,'categoria publicada');
select lives_ok($$select pg_temp.pub('save','live',0,pg_temp.fields('live')||jsonb_build_object('category',pg_temp.pi('category'),'channel',pg_temp.pi('channel')))$$,'transmissão vinculada ao canal e categoria');
select lives_ok($$select pg_temp.pub('publish','live',1)$$,'transmissão publicada');
select is(jsonb_array_length(public.member_media(pg_temp.pi('org'),pg_temp.pi('b'),'live')->'items'),1,'transmissão usa catálogo canônico do aplicativo');
select lives_ok($$select pg_temp.pub('live','live',2)$$,'início manual ao vivo');
select is(public.member_media(pg_temp.pi('org'),pg_temp.pi('a'),'live')->'items'->0->>'live_state','live','estado ao vivo sincronizado');
select throws_ok($$select pg_temp.pub('archive','channel',2)$$,'40001','publishing_changed','canal com transmissão publicada não é arquivado silenciosamente');
select lives_ok($$select pg_temp.pub('end','live',3)$$,'encerra transmissão sem prometer gravação');
select lives_ok($$select pg_temp.pub('archive','live',4)$$,'arquiva transmissão');
select is(jsonb_array_length(public.member_media(pg_temp.pi('org'),pg_temp.pi('b'),'live')->'items'),0,'arquivamento retira todas as cópias');
select lives_ok($$select pg_temp.pub('group','group',1,jsonb_build_object('title','Grupo modificado','targets',jsonb_build_array(pg_temp.pi('a')),'active',true))$$,'grupo pode mudar sem redistribuir conteúdo anterior');
select throws_ok($$select pg_temp.pub('publish','notice',2)$$,'40001','publishing_changed','grupo alterado exige conferir destinatários antes de nova publicação');
select lives_ok($$select pg_temp.pub('archive','notice',2)$$,'retirada explícita continua disponível');
select throws_ok($$select pg_temp.pub('publish','notice',2)$$,'40001','publishing_changed','revisão antiga recusada');
reset role;
select ok(not has_table_privilege('authenticated','private.publishing_items','select'),'itens privados');
select ok(not has_function_privilege('anon','public.publishing_admin(uuid,uuid,text,uuid,integer,jsonb)','execute'),'visitante não gerencia');
select ok(exists(select 1 from public.audit_logs where organization_id=pg_temp.pi('org') and action='publishing.publish'),'publicação auditada');
select * from finish();rollback;
